insert into public.battle_challenges (id, tier, title, public_data) values
  ('maior-de-dois', 1, 'O maior de dois', '{"id":"maior-de-dois","tier":1,"title":"O maior de dois","statement":"Complete `resolver(a, b)` para devolver o **maior** dos dois números.\n\nSe forem iguais, devolva qualquer um deles (são o mesmo valor).","constraints":["-1000 ≤ a, b ≤ 1000"],"signature":{"params":[{"name":"a","type":"int"},{"name":"b","type":"int"}],"returns":"int"},"examples":[{"input":[3,9],"output":"9"},{"input":[-2,-7],"output":"-2"}]}'::jsonb),
  ('par-ou-impar', 1, 'Par ou ímpar?', '{"id":"par-ou-impar","tier":1,"title":"Par ou ímpar?","statement":"Complete `resolver(n)` para devolver o texto `par` se `n` for par e `impar` (sem acento) se for ímpar.","constraints":["0 ≤ n ≤ 1.000.000"],"signature":{"params":[{"name":"n","type":"int"}],"returns":"str"},"examples":[{"input":[4],"output":"par"},{"input":[7],"output":"impar"}]}'::jsonb),
  ('calcular-troco', 1, 'Quanto de troco?', '{"id":"calcular-troco","tier":1,"title":"Quanto de troco?","statement":"Um produto custa `preco` e o cliente pagou `pago` (os dois em centavos). Complete `resolver(preco, pago)` para devolver o troco.\n\nSe o dinheiro **não for suficiente**, devolva `-1`.","constraints":["1 ≤ preco, pago ≤ 100.000"],"signature":{"params":[{"name":"preco","type":"int"},{"name":"pago","type":"int"}],"returns":"int"},"examples":[{"input":[350,500],"output":"150"},{"input":[1000,1000],"output":"0"},{"input":[800,500],"output":"-1"}]}'::jsonb),
  ('conceito-da-nota', 1, 'Conceito da nota', '{"id":"conceito-da-nota","tier":1,"title":"Conceito da nota","statement":"Complete `resolver(nota)` para devolver o conceito:\n\n`A` para 90 ou mais, `B` de 70 a 89, `C` de 50 a 69 e `D` abaixo de 50.","constraints":["0 ≤ nota ≤ 100"],"signature":{"params":[{"name":"nota","type":"int"}],"returns":"str"},"examples":[{"input":[95],"output":"A"},{"input":[70],"output":"B"},{"input":[12],"output":"D"}]}'::jsonb),
  ('soma-ate-n', 2, 'Soma de 1 até N', '{"id":"soma-ate-n","tier":2,"title":"Soma de 1 até N","statement":"Complete `resolver(n)` para devolver `1 + 2 + 3 + ... + n`.\n\nPara `n = 0`, a soma é `0`.","constraints":["0 ≤ n ≤ 20.000"],"signature":{"params":[{"name":"n","type":"int"}],"returns":"int"},"examples":[{"input":[4],"output":"10"},{"input":[10],"output":"55"}]}'::jsonb),
  ('contar-letra', 2, 'Quantas vezes aparece?', '{"id":"contar-letra","tier":2,"title":"Quantas vezes aparece?","statement":"Complete `resolver(texto, letra)` para contar quantas vezes `letra` (um único caractere) aparece em `texto`.","constraints":["texto tem de 1 a 200 letras minúsculas, sem espaços","letra é uma única letra minúscula"],"signature":{"params":[{"name":"texto","type":"str"},{"name":"letra","type":"str"}],"returns":"int"},"examples":[{"input":["banana","a"],"output":"3"},{"input":["programacao","z"],"output":"0"}]}'::jsonb),
  ('quantos-digitos', 2, 'Quantos dígitos?', '{"id":"quantos-digitos","tier":2,"title":"Quantos dígitos?","statement":"Complete `resolver(n)` para devolver quantos dígitos `n` tem.\n\nO número `0` tem 1 dígito. Tente resolver com divisões por 10 em um laço.","constraints":["0 ≤ n ≤ 2.000.000.000"],"signature":{"params":[{"name":"n","type":"int"}],"returns":"int"},"examples":[{"input":[2026],"output":"4"},{"input":[7],"output":"1"}]}'::jsonb),
  ('palavra-ao-contrario', 2, 'Palavra ao contrário', '{"id":"palavra-ao-contrario","tier":2,"title":"Palavra ao contrário","statement":"Complete `resolver(palavra)` para devolver a palavra escrita de trás para frente.","constraints":["palavra tem de 1 a 100 letras minúsculas"],"signature":{"params":[{"name":"palavra","type":"str"}],"returns":"str"},"examples":[{"input":["codigo"],"output":"ogidoc"},{"input":["arara"],"output":"arara"}]}'::jsonb),
  ('soma-dos-pares', 3, 'Soma dos pares', '{"id":"soma-dos-pares","tier":3,"title":"Soma dos pares","statement":"Complete `resolver(v)` para devolver a soma dos números **pares** da lista `v`.\n\nLista sem pares (ou vazia) dá `0`. Números negativos também podem ser pares.","constraints":["0 ≤ tamanho de v ≤ 1000","-1000 ≤ v[i] ≤ 1000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int"},"examples":[{"input":[[1,2,3,4]],"output":"6"},{"input":[[-6,5,0]],"output":"-6"}]}'::jsonb),
  ('menor-e-maior', 3, 'Menor e maior', '{"id":"menor-e-maior","tier":3,"title":"Menor e maior","statement":"Complete `resolver(v)` para devolver uma lista com dois números: o **menor** e o **maior** valor de `v`, nessa ordem.","constraints":["1 ≤ tamanho de v ≤ 1000","-100.000 ≤ v[i] ≤ 100.000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int[]"},"examples":[{"input":[[4,-2,9,0]],"output":"-2 9"},{"input":[[7]],"output":"7 7"}]}'::jsonb),
  ('acima-da-media', 3, 'Acima da média', '{"id":"acima-da-media","tier":3,"title":"Acima da média","statement":"Complete `resolver(v)` para contar quantos números de `v` são **maiores** que a média da lista.\n\nDica: dá para evitar números com vírgula comparando `x * tamanho > soma`.","constraints":["1 ≤ tamanho de v ≤ 1000","0 ≤ v[i] ≤ 1000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int"},"examples":[{"input":[[2,4,6]],"output":"1"},{"input":[[5,5,5,5]],"output":"0"}]}'::jsonb),
  ('segundo-maior-distinto', 4, 'O vice-campeão', '{"id":"segundo-maior-distinto","tier":4,"title":"O vice-campeão","statement":"Complete `resolver(v)` para devolver o **segundo maior valor diferente** da lista.\n\nEm `[5, 9, 9, 2]` a resposta é `5`. A lista sempre tem pelo menos dois valores diferentes.","constraints":["2 ≤ tamanho de v ≤ 1000","-10.000 ≤ v[i] ≤ 10.000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int"},"examples":[{"input":[[5,9,9,2]],"output":"5"},{"input":[[1,2]],"output":"1"}]}'::jsonb),
  ('palavra-mais-longa', 4, 'A palavra mais longa', '{"id":"palavra-mais-longa","tier":4,"title":"A palavra mais longa","statement":"Complete `resolver(frase)` para devolver a palavra mais longa da frase.\n\nAs palavras estão separadas por **um** espaço. Em empate, devolva a que aparece primeiro.","constraints":["a frase tem de 1 a 50 palavras de letras minúsculas","cada palavra tem de 1 a 15 letras"],"signature":{"params":[{"name":"frase","type":"str"}],"returns":"str"},"examples":[{"input":["eu gosto de programar"],"output":"programar"},{"input":["sol mar ceu"],"output":"sol"}]}'::jsonb),
  ('girar-lista', 4, 'Girar a lista', '{"id":"girar-lista","tier":4,"title":"Girar a lista","statement":"Complete `resolver(v, k)` para mover cada elemento `k` posições para a **direita**; quem sai do fim volta para o começo.\n\n`v = [1, 2, 3, 4]` e `k = 1` dá `[4, 1, 2, 3]`. O `k` pode ser maior que o tamanho.","constraints":["1 ≤ tamanho de v ≤ 1000","0 ≤ k ≤ 1.000.000"],"signature":{"params":[{"name":"v","type":"int[]"},{"name":"k","type":"int"}],"returns":"int[]"},"examples":[{"input":[[1,2,3,4],1],"output":"4 1 2 3"},{"input":[[1,2,3],5],"output":"2 3 1"}]}'::jsonb),
  ('colchetes-balanceados', 5, 'Colchetes em ordem', '{"id":"colchetes-balanceados","tier":5,"title":"Colchetes em ordem","statement":"Complete `resolver(s)` para devolver `true` se todos os `()`, `[]` e `{}` abrem e fecham na ordem certa, e `false` caso contrário.\n\n`{[()]}` está certo; `([)]` e `((` não estão.","constraints":["1 ≤ tamanho de s ≤ 10.000","s só tem os caracteres ()[]{}"],"signature":{"params":[{"name":"s","type":"str"}],"returns":"bool"},"examples":[{"input":["{[()]}"],"output":"true"},{"input":["([)]"],"output":"false"},{"input":["(("],"output":"false"}]}'::jsonb),
  ('busca-na-lista-ordenada', 5, 'Achar na lista ordenada', '{"id":"busca-na-lista-ordenada","tier":5,"title":"Achar na lista ordenada","statement":"A lista `v` está em ordem crescente e não tem repetidos. Complete `resolver(v, alvo)` para devolver a **posição** (começando em 0) de `alvo`, ou `-1` se ele não estiver na lista.\n\nUma busca binária resolve em poucos passos mesmo com listas grandes.","constraints":["1 ≤ tamanho de v ≤ 50.000","-1.000.000 ≤ v[i], alvo ≤ 1.000.000"],"signature":{"params":[{"name":"v","type":"int[]"},{"name":"alvo","type":"int"}],"returns":"int"},"examples":[{"input":[[1,3,5,7,9],7],"output":"3"},{"input":[[2,4],3],"output":"-1"}]}'::jsonb),
  ('compactar-texto', 5, 'Compactar texto', '{"id":"compactar-texto","tier":5,"title":"Compactar texto","statement":"Complete `resolver(s)` para trocar cada sequência de letras iguais pela letra seguida da quantidade.\n\n`aaabcc` vira `a3b1c2`.","constraints":["1 ≤ tamanho de s ≤ 10.000","s só tem letras minúsculas"],"signature":{"params":[{"name":"s","type":"str"}],"returns":"str"},"examples":[{"input":["aaabcc"],"output":"a3b1c2"},{"input":["abc"],"output":"a1b1c1"}]}'::jsonb),
  ('pares-que-somam', 6, 'Pares que somam o alvo', '{"id":"pares-que-somam","tier":6,"title":"Pares que somam o alvo","statement":"A lista `v` tem números **diferentes**. Complete `resolver(v, alvo)` para contar quantos pares de posições `i < j` têm `v[i] + v[j] == alvo`.\n\nAs listas podem ter 100 mil números: dois laços aninhados estouram o tempo. Pense em guardar o que você já viu.","constraints":["1 ≤ tamanho de v ≤ 100.000","valores distintos entre -1.000.000 e 1.000.000","-2.000.000 ≤ alvo ≤ 2.000.000"],"signature":{"params":[{"name":"v","type":"int[]"},{"name":"alvo","type":"int"}],"returns":"int"},"examples":[{"input":[[1,5,3,7,2],8],"output":"2"},{"input":[[4,6],3],"output":"0"}]}'::jsonb),
  ('melhor-sequencia', 6, 'A melhor sequência', '{"id":"melhor-sequencia","tier":6,"title":"A melhor sequência","statement":"Complete `resolver(v)` para devolver a **maior soma** de um trecho contínuo (com pelo menos um número) da lista.\n\nEm `[-2, 1, -3, 4, -1, 2, 1, -5, 4]` a resposta é `6` (`4, -1, 2, 1`). Com 100 mil números, testar todos os trechos é lento demais.","constraints":["1 ≤ tamanho de v ≤ 100.000","-10.000 ≤ v[i] ≤ 10.000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int"},"examples":[{"input":[[-2,1,-3,4,-1,2,1,-5,4]],"output":"6"},{"input":[[-3,-1,-2]],"output":"-1"}]}'::jsonb),
  ('contar-primos', 6, 'Quantos primos?', '{"id":"contar-primos","tier":6,"title":"Quantos primos?","statement":"Complete `resolver(n)` para devolver quantos números primos existem de `2` até `n` (inclusive).\n\nCom `n` até 2 milhões, testar divisor por divisor é lento. Pesquise o Crivo de Eratóstenes.","constraints":["0 ≤ n ≤ 2.000.000"],"signature":{"params":[{"name":"n","type":"int"}],"returns":"int"},"examples":[{"input":[10],"output":"4"},{"input":[2],"output":"1"}]}'::jsonb)
