-- GERADO AUTOMATICAMENTE por scripts/generate-battle-config.mts — só a parte PÚBLICA dos desafios.
begin;
on conflict (id) do update set tier = excluded.tier, title = excluded.title, public_data = excluded.public_data, enabled = true;
update public.battle_challenges set enabled = false where id not in ('maior-de-dois', 'par-ou-impar', 'calcular-troco', 'conceito-da-nota', 'soma-ate-n', 'contar-letra', 'quantos-digitos', 'palavra-ao-contrario', 'soma-dos-pares', 'menor-e-maior', 'acima-da-media', 'segundo-maior-distinto', 'palavra-mais-longa', 'girar-lista', 'colchetes-balanceados', 'busca-na-lista-ordenada', 'compactar-texto', 'pares-que-somam', 'melhor-sequencia', 'contar-primos');
commit;
